const express = require("express");
const app = express();
app.use(express.json());

function kirimError(res, status, code, message, details) {
  const error = { code, message };
  if (details) error.details = details;
  return res.status(status).json({ error });
}

function cariBuku(id) {
  return BUKU.find((b) => b.id === Number(id));
}

function bukuTidakAda(res, id) {
  return kirimError(res, 404, "BUKU_TIDAK_DITEMUKAN", "Buku dengan id " + id + " tidak ditemukan");
}

function teksWajib(nilai) {
  return typeof nilai === "string" && nilai.trim() !== "";
}

// parsial: true untuk PATCH, hanya field yang dikirim yang diperiksa
function validasiBuku(data, parsial) {
  const details = [];
  const ada = (f) => !parsial || data[f] !== undefined;
  if (ada("judul") && !teksWajib(data.judul)) details.push({ field: "judul", message: "judul wajib diisi" });
  if (ada("penulis") && !teksWajib(data.penulis)) details.push({ field: "penulis", message: "penulis wajib diisi" });
  if (ada("kategori") && !KATEGORI.includes(data.kategori)) {
    details.push({ field: "kategori", message: "kategori harus salah satu dari " + KATEGORI.join(", ") });
  }
  if (ada("tahun") && !(Number.isInteger(data.tahun) && data.tahun >= 1450 && data.tahun <= 2100)) {
    details.push({ field: "tahun", message: "tahun harus bilangan bulat 1450 sampai 2100" });
  }
  if (data.stok !== undefined && !(Number.isInteger(data.stok) && data.stok >= 0)) {
    details.push({ field: "stok", message: "stok harus bilangan bulat 0 atau lebih" });
  }
  return details;
}

const BOLEH_SORT = ["judul", "tahun"];

app.get("/v1/buku", (req, res) => {
  let hasil = BUKU;
  if (req.query.kategori) hasil = hasil.filter((b) => b.kategori === req.query.kategori);

  if (req.query.sort) {
    const turun = req.query.sort.startsWith("-");
    const field = turun ? req.query.sort.slice(1) : req.query.sort;
    if (!BOLEH_SORT.includes(field)) {
      return kirimError(res, 400, "SORT_TIDAK_VALID", "sort hanya boleh judul, -judul, tahun, atau -tahun");
    }
    const arah = turun ? -1 : 1;
    hasil = [...hasil].sort((a, b) => (a[field] > b[field] ? 1 : a[field] < b[field] ? -1 : 0) * arah);
  }

  const per = Math.min(50, Math.max(1, parseInt(req.query.per, 10) || 10));
  const halaman = Math.max(1, parseInt(req.query.halaman, 10) || 1);
  const total = hasil.length;
  res.json({
    data: hasil.slice((halaman - 1) * per, halaman * per),
    meta: { total, halaman, per, totalHalaman: Math.ceil(total / per) },
  });
});

app.get("/v1/buku/:id", (req, res) => {
  const buku = cariBuku(req.params.id);
  if (!buku) return bukuTidakAda(res, req.params.id);
  res.json(buku);
});

app.post("/v1/buku", (req, res) => {
  const details = validasiBuku(req.body, false);
  if (details.length) return kirimError(res, 422, "VALIDASI_GAGAL", "Data buku tidak valid", details);
  const { judul, penulis, kategori, tahun, stok } = req.body;
  const id = BUKU.reduce((maks, b) => Math.max(maks, b.id), 0) + 1;
  const baru = { id, judul: judul.trim(), penulis: penulis.trim(), kategori, tahun, stok: stok === undefined ? 1 : stok };
  BUKU.push(baru);
  res.set("Location", "/v1/buku/" + id);
  res.status(201).json(baru);
});

app.patch("/v1/buku/:id", (req, res) => {
  const buku = cariBuku(req.params.id);
  if (!buku) return bukuTidakAda(res, req.params.id);
  const details = validasiBuku(req.body, true);
  if (details.length) return kirimError(res, 422, "VALIDASI_GAGAL", "Data buku tidak valid", details);
  for (const f of ["judul", "penulis", "kategori", "tahun", "stok"]) {
    if (req.body[f] !== undefined) buku[f] = typeof req.body[f] === "string" ? req.body[f].trim() : req.body[f];
  }
  res.json(buku);
});

app.delete("/v1/buku/:id", (req, res) => {
  const i = BUKU.findIndex((b) => b.id === Number(req.params.id));
  if (i === -1) return bukuTidakAda(res, req.params.id);
  BUKU.splice(i, 1);
  res.status(204).end();
});

app.post("/v1/buku/:id/peminjaman", (req, res) => {
  const buku = cariBuku(req.params.id);
  if (!buku) return bukuTidakAda(res, req.params.id);
  if (!teksWajib(req.body.nis)) {
    return kirimError(res, 422, "VALIDASI_GAGAL", "Data peminjaman tidak valid", [{ field: "nis", message: "nis wajib diisi" }]);
  }
  if (buku.stok < 1) return kirimError(res, 409, "STOK_HABIS", "Stok buku " + buku.judul + " sedang habis");
  buku.stok -= 1;
  const pinjam = { id: PEMINJAMAN.length + 1, bukuId: buku.id, nis: req.body.nis };
  PEMINJAMAN.push(pinjam);
  res.status(201).json(pinjam);
});

chapters.body:
## Tujuan

- Menjelaskan apa itu API dan peran klien serta server.
- Memahami prinsip utama REST: resource, representasi, stateless, dan client-server.
- Membedakan REST dengan gaya RPC dan GraphQL secara singkat.
- Menulis dua route Express pertama yang mengikuti gaya REST.

## API itu kontrak

Kamu sudah bisa membuat route di Express. Route `app.get("/buku", ...)` yang kamu tulis sebenarnya adalah bagian dari sebuah API. API (Application Programming Interface) adalah kontrak yang menjelaskan cara satu program meminta sesuatu ke program lain. Di dunia web, kontrak itu berbentuk URL, method HTTP, header, dan body JSON.

Bayangkan aplikasi perpustakaan sekolah. Ada aplikasi web untuk petugas, aplikasi HP untuk siswa, dan mungkin papan informasi di lobi yang menampilkan buku terbaru. Ketiganya disebut **klien**. Mereka semua mengambil data dari satu **server** yang sama. Supaya ketiga klien bisa bekerja, server harus menjanjikan hal yang jelas: "kalau kamu meminta `GET /buku/7`, kamu akan mendapat data buku nomor 7 dalam bentuk JSON".

Kalau janji itu berubah sembarangan, misalnya hari ini field-nya `judul` lalu besok jadi `title`, semua klien rusak. Karena itu kelas ini tidak membahas cara membuat route supaya jalan (itu sudah kamu bisa), melainkan cara **merancang** API supaya mudah ditebak, konsisten, dan tahan lama.

Contoh satu pertukaran request dan respons terlihat seperti ini:

```http
GET /buku/7 HTTP/1.1
Host: api.perpus.sch.id
Accept: application/json

HTTP/1.1 200 OK
Content-Type: application/json

{ "id": 7, "judul": "Laskar Pelangi", "penulis": "Andrea Hirata" }
```

Baris pertama request berisi method (`GET`) dan path (`/buku/7`). Respons diawali status code (`200 OK`), lalu header, lalu body. Seluruh kelas ini sebenarnya membahas cara memilih isi setiap bagian itu dengan baik.

## Apa itu REST

REST (Representational State Transfer) adalah gaya arsitektur yang dirumuskan Roy Fielding dalam disertasinya pada tahun 2000. REST bukan library dan bukan aturan resmi yang dicek oleh mesin. Ia adalah kumpulan prinsip. API yang mengikuti prinsip itu disebut RESTful.

![Empat prinsip REST yang paling sering dipakai](slide:3)

Ada beberapa prinsip yang perlu kamu pegang.

**Resource.** Semua yang bisa diberi nama adalah resource: buku, anggota, peminjaman, kelas, nilai rapor. Setiap resource punya alamat sendiri berupa URL. Koleksi buku ada di `/buku`, satu buku ada di `/buku/7`.

**Representasi.** Server tidak mengirim "buku" itu sendiri, melainkan gambarannya dalam format tertentu. Hampir semua API modern memakai JSON. Data yang sama bisa saja disimpan sebagai baris tabel MySQL di server, tetapi yang dikirim ke klien adalah representasi JSON-nya.

**Stateless.** Server tidak mengingat percakapan sebelumnya dengan klien. Setiap request harus membawa semua informasi yang dibutuhkan, termasuk siapa pengirimnya (biasanya lewat token di header). Keuntungannya, request mana pun bisa dilayani server mana pun, sehingga mudah menambah server saat pengguna bertambah.

**Client-server.** Klien mengurus tampilan, server mengurus data dan aturan bisnis. Keduanya boleh berkembang terpisah selama kontraknya tetap. Tim aplikasi HP bisa mengganti desain tanpa menunggu tim server.

**Antarmuka seragam.** Semua resource diperlakukan dengan cara yang sama: method HTTP standar (`GET`, `POST`, `PUT`, `PATCH`, `DELETE`) dan status code standar (`200`, `404`, dan teman-temannya). Programmer yang sudah kenal satu API REST bisa langsung menebak cara memakai API REST lain.

Prinsip lain seperti respons yang bisa di-cache akan kamu temui lagi di bab caching.

## Stateless dalam praktik

Mari lihat contoh yang melanggar prinsip stateless. Misalkan server menyimpan "halaman terakhir yang dilihat" di variabel global:

```js
let halamanTerakhir = 1;

app.get("/buku/berikutnya", (req, res) => {
  halamanTerakhir++;
  res.json(ambilHalaman(halamanTerakhir));
});
```

Kalau dua siswa membuka aplikasi bersamaan, mereka saling menggeser halaman satu sama lain. Kalau server di-restart, posisinya hilang. Versi stateless meminta klien menyebutkan halamannya sendiri:

```js
app.get("/buku", (req, res) => {
  const halaman = Number(req.query.halaman) || 1;
  res.json(ambilHalaman(halaman));
});
```

Sekarang setiap request berdiri sendiri. Request `GET /buku?halaman=3` selalu berarti hal yang sama, siapa pun pengirimnya dan server mana pun yang menjawab.

Perlu dicatat, stateless bukan berarti server tidak boleh menyimpan data. Database tetap menyimpan buku dan anggota. Yang dilarang adalah menyimpan **keadaan percakapan** dengan klien tertentu di memori server.

## REST dan alternatifnya

REST bukan satu-satunya gaya. Ada dua alternatif yang sering kamu dengar.

**RPC (Remote Procedure Call).** Gaya ini memperlakukan API sebagai kumpulan fungsi. URL-nya berupa kata kerja, misalnya `POST /ambilNilaiSiswa` atau `POST /hitungRataRata`. Gaya ini terasa alami bagi programmer karena mirip memanggil fungsi, tetapi setiap API punya nama fungsi sendiri yang harus dihafal. gRPC adalah contoh RPC modern yang populer untuk komunikasi antarserver.

**GraphQL.** Hanya ada satu endpoint, biasanya `POST /graphql`. Klien mengirim query yang menyebut field apa saja yang ia mau. Cocok untuk aplikasi dengan tampilan rumit yang butuh data dari banyak resource sekaligus, tetapi lebih sulit di-cache dan butuh library khusus di server.

```text
# REST
GET  /siswa/12/nilai

# RPC
POST /ambilNilaiSiswa   { "id": 12 }

# GraphQL
POST /graphql
{ siswa(id: 12) { nama nilai { mapel angka } } }
```

Ketiganya sah dipakai. REST paling umum untuk API publik dan aplikasi web biasa karena memanfaatkan fitur HTTP yang sudah ada: method, status code, dan cache. Itulah alasan kelas ini fokus ke REST.

## Route pertama yang RESTful

Dengan prinsip di atas, dua route paling dasar untuk koleksi buku terlihat seperti ini:

```js
const express = require("express");
const app = express();
app.use(express.json());

const BUKU = [
  { id: 1, judul: "Laskar Pelangi", penulis: "Andrea Hirata" },
  { id: 2, judul: "Bumi", penulis: "Tere Liye" },
];

app.get("/buku", (req, res) => {
  res.json({ data: BUKU });
});

app.get("/buku/:id", (req, res) => {
  const buku = BUKU.find((b) => b.id === Number(req.params.id));
  if (!buku) return res.status(404).json({ error: { message: "Buku tidak ditemukan" } });
  res.json(buku);
});
```

Perhatikan tiga hal. Pertama, URL hanya berisi kata benda (`buku`), aksinya ditentukan method `GET`. Kedua, `req.params.id` selalu berupa string, jadi perlu `Number()` sebelum dibandingkan dengan id angka. Ketiga, buku yang tidak ada dijawab dengan status `404`, bukan `200` dengan pesan "tidak ada". Ketiga kebiasaan ini akan dibahas lebih dalam di bab-bab berikutnya.

## Melihat API dari sisi klien

Desain API paling mudah dinilai dari sisi orang yang memakainya. Coba bayangkan kamu adalah programmer aplikasi web perpustakaan yang memanggil route di atas dengan `fetch`:

```js
const res = await fetch("https://api.perpus.sch.id/buku/7");
if (res.status === 404) {
  tampilkanPesan("Buku tidak ditemukan");
} else {
  const buku = await res.json();
  tampilkanBuku(buku);
}
```

Kode klien ini pendek karena API-nya bisa ditebak: URL jelas, status code jujur, dan bentuk JSON-nya tetap. Sekarang bayangkan API yang selalu membalas 200 lalu menaruh keterangan berhasil atau gagal di field yang namanya berubah-ubah antarendpoint. Klien harus menulis pemeriksaan khusus untuk setiap endpoint, dan setiap perubahan kecil di server berisiko merusak aplikasi.

Selama kelas ini, biasakan bertanya dua hal setiap kali merancang endpoint: "Bisakah orang lain menebak URL ini tanpa dokumentasi?" dan "Bisakah klien menangani responsnya tanpa membaca kode server?" Kalau jawabannya ya, desainmu sudah di jalur yang benar.

## Rangkuman

- API adalah kontrak antara klien dan server; di web kontraknya berupa URL, method, header, status code, dan JSON.
- REST adalah gaya arsitektur, bukan library: data dimodelkan sebagai resource dengan URL sendiri dan dikirim sebagai representasi JSON.
- Stateless berarti setiap request membawa semua informasi yang dibutuhkan; server tidak menyimpan keadaan percakapan di memori.
- RPC memakai nama fungsi sebagai URL, GraphQL memakai satu endpoint dengan query; REST paling umum karena memanfaatkan fitur HTTP.
- Kebiasaan dasar: URL kata benda, method sebagai aksi, dan status code yang jujur.

