const express = require("express");
const app = express();
app.use(express.json());

const BOLEH_SORT = ["nama", "harga"];

app.get("/produk", (req, res) => {
  let hasil = PRODUK;
  if (req.query.kategori) hasil = hasil.filter((p) => p.kategori === req.query.kategori);

  if (req.query.sort) {
    const turun = req.query.sort.startsWith("-");
    const field = turun ? req.query.sort.slice(1) : req.query.sort;
    if (!BOLEH_SORT.includes(field)) {
      return res.status(400).json({ error: { code: "SORT_TIDAK_VALID", message: "sort hanya boleh nama atau harga" } });
    }
    const arah = turun ? -1 : 1;
    hasil = [...hasil].sort((a, b) => (a[field] > b[field] ? 1 : a[field] < b[field] ? -1 : 0) * arah);
  }

  const per = Math.min(20, Math.max(1, parseInt(req.query.per, 10) || 5));
  const halaman = Math.max(1, parseInt(req.query.halaman, 10) || 1);
  res.json({
    data: hasil.slice((halaman - 1) * per, halaman * per),
    meta: { total: hasil.length, halaman, per },
  });
});

