const express = require("express");
const app = express();
app.use(express.json());

app.get("/menu", (req, res) => {
  const etag = '"' + hash(JSON.stringify(MENU)) + '"';
  res.set("ETag", etag);
  res.set("Cache-Control", "no-cache");
  if (req.headers["if-none-match"] === etag) return res.status(304).end();
  res.json({ data: MENU });
});

app.patch("/menu/:id", (req, res) => {
  const m = MENU.find((x) => x.id === Number(req.params.id));
  if (!m) return res.status(404).json({ error: { code: "MENU_TIDAK_DITEMUKAN", message: "Menu tidak ditemukan" } });
  if (req.body.harga !== undefined) m.harga = req.body.harga;
  res.json(m);
});

