const express = require("express");
const app = express();
app.use(express.json());

const BATAS = 3;
const hitungan = new Map();

function batasi(req, res, next) {
  const kunci = req.headers["x-api-key"] || "anonim";
  const n = (hitungan.get(kunci) || 0) + 1;
  hitungan.set(kunci, n);
  res.set("X-RateLimit-Remaining", String(Math.max(0, BATAS - n)));
  if (n > BATAS) {
    res.set("Retry-After", "60");
    return res.status(429).json({ error: { code: "TERLALU_BANYAK_REQUEST", message: "Batas " + BATAS + " request, coba lagi nanti" } });
  }
  next();
}

app.use(batasi);
app.get("/menu-hari-ini", (req, res) => res.json({ data: ["Nasi Goreng", "Soto Ayam"] }));

