const METHOD = ["get", "post", "put", "patch", "delete"];

function cekSpesifikasi(spec) {
  const masalah = [];
  if (typeof spec.openapi !== "string" || !spec.openapi.startsWith("3.1.")) masalah.push("VERSI");
  if (!spec.info || !spec.info.title || !spec.info.version) masalah.push("INFO");

  for (const path of Object.keys(spec.paths || {})) {
    const nama = (path.match(/\{[^}]+\}/g) || []).map((x) => x.slice(1, -1));
    for (const m of METHOD) {
      const op = spec.paths[path][m];
      if (!op) continue;
      const label = m.toUpperCase() + " " + path;
      if (!op.responses || Object.keys(op.responses).length === 0) masalah.push("RESPONS " + label);
      for (const n of nama) {
        const p = (op.parameters || []).find((x) => x.in === "path" && x.name === n);
        if (!p || p.required !== true) masalah.push("PARAM " + n + " " + label);
      }
    }
  }
  return masalah;
}

